CREATE TEMPORARY VIEW raw_dim_and_metrics_${grass_region_without_quote} AS
SELECT
    item_id
    ,COALESCE(CAST(level1_global_be_category_id AS STRING), '') AS level1_global_be_category_id
    ,CAST(has_video AS STRING) AS has_video
    ,CAST(skip_mab AS STRING) AS skip_mab
    ,card_type
    ,COUNT(DISTINCT CASE WHEN content_id = '__ALL__' THEN NULL ELSE content_id END) AS content_id_count
    ,SUM(IF(content_id = '__ALL__', imp_cnt, 0)) AS imp_cnt
    ,SUM(IF(content_id = '__ALL__', click_cnt, 0)) AS click_cnt
    ,SUM(IF(content_id = '__ALL__', order_cnt, 0)) AS order_cnt
    ,SUM(IF(content_id = '__ALL__', gmv, 0)) AS gmv
FROM
    srdi_mart.dws_sr_data_warehouse_search_card_mab_analysis_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    AND sub_product_type = '__ALL__'
GROUP BY
    1,2,3,4,5;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_cat_${grass_region_without_quote} AS
SELECT DISTINCT
    COALESCE(level1_global_be_category, '') AS level1_global_be_category
    ,COALESCE(CAST(level1_global_be_category_id AS STRING), '') AS level1_global_be_category_id
